INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (320, 0, 10, "", 20, "", 0, 23001, 0, 20001, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (321, 0, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, "リリ", 1, 24001, 125801, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (322, 0, 2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 1, "クリア", 1, 24001, 126001, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (323, 0, 3, "んーと。\nこれ、あげる。\nはい", 1, "プレシア", 1, 24001, 126101, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (324, 0, 4, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 1, "リリ", 2, 24001, 125801, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (325, 0, 5, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 1, "クリア", 2, 24001, 126001, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (326, 0, 6, "お兄。\nきてくれて、うれしい", 1, "プレシア", 2, 24001, 126101, 40011, 2);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (327, 532001, 1, "", 100, "", 0, 91002, 0, 80009, 8);
